import React, { useEffect, useRef } from 'react';

/**
 * Usa dos modos:
 *  - GRUPOS:  <ProductSlider groups={[{id, title?, variant?, products:[{id,imageUrl|image},...]}, ...]} />
 *  - LEGACY:  <ProductSlider images={[{id,imageUrl|image}, ...]} />
 *
 * No requiere CSS global: estilos embebidos y scopeados a .ps-root
 */
export default function ProductSlider({ id, groups = [], images = [] }) {
  const trackRef = useRef(null);

  // ---- helpers
  // Normaliza la entrada: siempre trabajamos con "slides" que contienen un array products
  const slides = (groups && groups.length)
    ? groups.map(g => ({
        ...g,
        products: (g.products || []).map(p => ({
          id: p.id,
          imageUrl: p.imageUrl || p.image || '/placeholder.png'
        }))
      }))
    : (images || []).map(img => ({
        id: img.id,
        products: [{ id: img.id, imageUrl: img.imageUrl || img.image || '/placeholder.png' }]
      }));

  // Navegación por "página" (un slide entero)
  const pageDeltaPx = () => {
    const track = trackRef.current;
    if (!track) return 0;
    const slide = track.querySelector('.ps-card');
    if (!slide) return 0;
    const rect = slide.getBoundingClientRect();
    const styles = getComputedStyle(track);
    const gap = parseFloat(styles.gap || styles.columnGap || 0);
    return rect.width + gap;
  };

  const go = (dir) => {
    const delta = pageDeltaPx();
    if (!delta) return;
    trackRef.current?.scrollBy({ left: dir * delta, behavior: 'smooth' });
  };

  // Drag / swipe
  useEffect(() => {
    const el = trackRef.current;
    if (!el) return;
    let isDown = false, startX = 0, scrollLeft = 0;
    const pt = (e) => (e.touches ? e.touches[0].pageX : e.pageX);
    const down = (e) => { isDown = true; startX = pt(e); scrollLeft = el.scrollLeft; };
    const move = (e) => {
      if (!isDown) return;
      e.preventDefault();
      const x = pt(e);
      el.scrollLeft = scrollLeft - (x - startX);
    };
    const up = () => { isDown = false; };

    el.addEventListener('mousedown', down);
    el.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
    el.addEventListener('touchstart', down, { passive: true });
    el.addEventListener('touchmove', move,  { passive: false });
    window.addEventListener('touchend', up);

    return () => {
      el.removeEventListener('mousedown', down);
      el.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
      el.removeEventListener('touchstart', down);
      el.removeEventListener('touchmove', move);
      window.removeEventListener('touchend', up);
    };
  }, []);

  return (
    <div className="ps-root" id={id}>
      <button className="ps-nav prev" onClick={() => go(-1)} aria-label="Anterior">‹</button>

      <div className="ps-track" ref={trackRef}>
        {slides.map((g, idx) => {
          const n = g.products?.length || 0;
          const clsCount = n >= 1 && n <= 4 ? `pg-n-${n}` : 'pg-n-auto';
          const clsVar   = g.variant ? `pg-${g.variant}` : '';
          return (
            <div className={`ps-card pg-card ${clsCount} ${clsVar}`} key={g.id ?? idx}>
              <div className="pg-grid">
                {(g.products || []).map((p, i) => (
                  <a key={p.id ?? i} className="pg-item" href={`/producto/${p.id}`}>
                    <img src={p.imageUrl} alt="" loading="lazy" />
                  </a>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <button className="ps-nav next" onClick={() => go(1)} aria-label="Siguiente">›</button>

      {/* CSS scopeado */}
      <style>{`
        .ps-root{
          position:relative;
          width:100%;
          max-width:1100px;
          margin: 10px auto 24px;
          padding: 0 42px; /* espacio para flechas */
        }
        .ps-track{
          display:flex;
          gap:16px;
          overflow-x:auto;
          scroll-behavior:smooth;
          scroll-snap-type:x mandatory;
          -webkit-overflow-scrolling:touch;
          padding-bottom:6px;
        }
        .ps-track::-webkit-scrollbar{ height:8px; }
        .ps-track::-webkit-scrollbar-thumb{ background:#e5e7eb; border-radius:8px; }

        .ps-card{
          flex: 0 0 100%;
          scroll-snap-align: start;
          background:#fff;
          border:1px solid #eee;
          border-radius:16px;
          box-shadow: 0 8px 24px rgba(0,0,0,.06);
          overflow:hidden;
        }

        /* Grid interna por slide */
        .pg-grid{
          display:grid;
          gap:12px;
          padding:12px;
        }
        .pg-grid .pg-item{
          display:block;
          border-radius:12px;
          overflow:hidden;
          border:1px solid #f0f0f0;
          background:#fafafa;
          transition: transform .12s ease, box-shadow .12s ease;
        }
        .pg-grid .pg-item:hover{
          transform: translateY(-2px);
          box-shadow: 0 10px 24px rgba(0,0,0,.10);
        }
        .pg-grid .pg-item img{
          width:100%; height:100%; object-fit:cover; display:block;
          aspect-ratio: 1 / 1;
        }

        /* Cantidades: 1..4 = grilla fija, >4 = auto (responsive) */
        .pg-card.pg-n-1 .pg-grid{ grid-template-columns: repeat(1, minmax(0,1fr)); }
        .pg-card.pg-n-2 .pg-grid{ grid-template-columns: repeat(2, minmax(0,1fr)); }
        .pg-card.pg-n-3 .pg-grid{ grid-template-columns: repeat(3, minmax(0,1fr)); }
        .pg-card.pg-n-4 .pg-grid{ grid-template-columns: repeat(4, minmax(0,1fr)); }
        .pg-card.pg-n-auto .pg-grid{ grid-template-columns: repeat(auto-fill, minmax(160px,1fr)); }

        /* Flechas */
        .ps-nav{
          position:absolute;
          top:50%;
          transform: translateY(-50%);
          width:34px; height:34px;
          border-radius:50%;
          border:0;
          cursor:pointer;
          display:grid; place-items:center;
          background:#fff;
          box-shadow: 0 6px 18px rgba(0,0,0,.18);
          color:#111;
          transition: transform .08s ease, box-shadow .12s ease, opacity .12s ease;
        }
        .ps-nav:hover{ transform: translateY(-50%) scale(1.03); }
        .ps-nav:active{ transform: translateY(-50%) scale(0.98); }
        .ps-nav.prev{ left: 6px; }
        .ps-nav.next{ right: 6px; }

        /* Responsivo: en móvil cada slide ocupa todo el ancho; en desktop también,
           pero la grilla interna distribuye más productos */
        @media(min-width: 900px){
          .ps-root{ padding: 0 48px; }
        }
      `}</style>
    </div>
  );
}
